+    if (file_path->isEmpty()) return save_payload_none;
+
+    save_payload_t save_format = save_payload_none;
+    if (0 == QString::compare(sel_filter, ext_filter_raw)) {
+        save_format = save_payload_data;
+    }
+
+    return save_format;
